<script setup>
import {ref,computed,watch,nextTick} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useIrrigation} from '../../data/runtime.js'
import {useListState} from '../../composables/useListState.js'
import {useDraftGuard} from '../../composables/useDraftGuard.js'
import BaseModal from '../../components/BaseModal.vue'
import DataTable from '../../components/DataTable.vue'
import Pagination from '../../components/Pagination.vue'
import StatusBadge from '../../components/StatusBadge.vue'
import MetricCard from '../../components/MetricCard.vue'
import FormField from '../../components/FormField.vue'
import {notify,confirmAction} from '../../composables/feedback.js'
import WorkOrderForm from './WorkOrderForm.vue'
import {columns,ordered,dateText,clone,alarmStates,severity,recovery,futureInput,isoInput,failureText} from './supportUi.js'
const r=useIrrigation(),route=useRoute(),router=useRouter(),state=useListState('alarms',{filters:{severity:'',status:'',recovery:''}})
if(route.query.selected)state.selectedId=route.query.selected
if(route.query.status)state.filters.status=String(route.query.status)
const statusOptions={...alarmStates,NOT_CLOSED:'待处理'}
const rows=computed(()=>ordered((r.state.entities.Alarm??[]).filter(a=>Object.entries(state.filters).every(([k,v])=>!v||(k==='status'&&v==='NOT_CLOSED'?a.status!=='CLOSED':a[k]===v))).sort((a,b)=>Date.parse(b.openedAt)-Date.parse(a.openedAt)),state.sort)),visible=computed(()=>rows.value.slice((state.page-1)*15,state.page*15)),selected=computed(()=>rows.value.find(a=>a.alarmId===state.selectedId)),work=computed(()=>(r.state.entities.WorkOrder??[]).find(w=>w.alarmId===selected.value?.alarmId))
watch(()=>JSON.stringify(state.filters),()=>state.page=1)
watch(visible,list=>{if(!list.some(a=>a.alarmId===state.selectedId))state.selectedId=list[0]?.alarmId??null},{immediate:true})
const cols=columns([['number','序号',80],['alarmId','告警编号',225],['deviceId','关联设备'],['severity','级别',120],['status','处理态',155],['recovery','恢复态',155],['openedAt','发生时间',180]])
const get=(kind,id)=>r.getIndex().byId[kind]?.get(id),modal=ref(false),snapshot=ref(null),mode=ref(''),note=ref(''),draft=ref({}),initial=ref(''),busy=ref(false),failure=ref(''),errors=ref({})
const dirty=computed(()=>modal.value&&JSON.stringify({mode:mode.value,note:note.value,draft:draft.value})!==initial.value),guard=useDraftGuard(()=>dirty.value)
function open(){if(!selected.value)return;snapshot.value=clone(selected.value);mode.value='';note.value='';draft.value={alarmId:snapshot.value.alarmId,zoneId:snapshot.value.zoneId??'',deviceId:snapshot.value.deviceId??'',kind:'DEVICE_REPAIR',assigneeId:'',dueAt:futureInput(),note:''};failure.value='';errors.value={};initial.value=JSON.stringify({mode:'',note:'',draft:draft.value});modal.value=true}
async function close(){if(busy.value)return;if(!dirty.value||await confirmAction({title:'放弃未保存内容',message:'当前处置说明尚未保存，确认放弃？',confirmText:'放弃'})){modal.value=false}else{modal.value=false;await nextTick();modal.value=true}}
function available(action){const a=snapshot.value;if(!a||!r.can(action,a))return false;if(action==='ALARM_ACK')return a.status==='OPEN';if(action==='WORKORDER_CREATE')return a.status!=='CLOSED'&&!(r.state.entities.WorkOrder??[]).some(w=>w.alarmId===a.alarmId&&w.status!=='COMPLETED');return ['ACKNOWLEDGED','ASSIGNED'].includes(a.status)&&a.recovery==='RECOVERED'&&!(r.state.entities.WorkOrder??[]).some(w=>w.alarmId===a.alarmId&&w.status!=='COMPLETED')}
async function submit(){if(!mode.value||!available(mode.value))return;busy.value=true;failure.value='';errors.value={};try{const payload=mode.value==='WORKORDER_CREATE'?{...draft.value,dueAt:isoInput(draft.value.dueAt)}:{alarmId:snapshot.value.alarmId,note:note.value,resolution:note.value};await r.commit(mode.value,payload,{expectedVersion:mode.value==='WORKORDER_CREATE'?undefined:snapshot.value.version,expectedVersions:mode.value==='WORKORDER_CREATE'?{[snapshot.value.alarmId]:snapshot.value.version}:undefined,clientRequestId:crypto.randomUUID()});notify('告警处置已保存');initial.value=JSON.stringify({mode:mode.value,note:note.value,draft:draft.value});modal.value=false;guard.markClean()}catch(e){failure.value=failureText(e);errors.value=e.fieldErrors??{}}finally{busy.value=false}}
</script>
<template><div class="page-stack alarm-page"><div class="alarm-filters"><label v-for="(opts,key) in {severity,status:statusOptions,recovery}" :key="key" class="filter-field">{{{severity:'严重度',status:'处理态',recovery:'恢复态'}[key]}}<select v-model="state.filters[key]"><option value="">全部</option><option v-for="(label,value) in opts" :key="value" :value="value">{{label}}</option></select></label></div><div class="stat-grid"><MetricCard label="全部告警" :value="rows.length" icon="alarm"/><MetricCard label="待处理" :value="rows.filter(a=>a.status!=='CLOSED').length" icon="calendar" tone="warning"/><MetricCard label="未恢复" :value="rows.filter(a=>a.recovery==='ACTIVE').length" icon="alarm" tone="danger"/><MetricCard label="已关闭" :value="rows.filter(a=>a.status==='CLOSED').length" icon="check"/></div><section class="panel alarm-table"><DataTable :columns="cols" :rows="visible" row-key="alarmId" :selected-id="state.selectedId" :sort="state.sort" compact @row-click="state.selectedId=$event.alarmId" @update:sort="state.sort=$event"><template #cell-number="{index}">{{(state.page-1)*15+index+1}}</template><template #cell-deviceId="{value}"><button class="btn-link device-link" @click.stop="router.push('/devices/'+value)">{{get('Device',value)?.name||value}}</button></template><template #cell-severity="{value}"><StatusBadge :status="value" :text="severity[value]" :tone="{HIGH:'danger',MEDIUM:'warning',LOW:'success'}[value]"/></template><template #cell-status="{value,row}"><button class="state-button" @click.stop="state.selectedId=row.alarmId;open()"><StatusBadge :status="value" :text="alarmStates[value]"/></button></template><template #cell-recovery="{value}"><StatusBadge :status="value" :text="recovery[value]" :tone="value==='ACTIVE'?'danger':'success'"/></template><template #cell-openedAt="{value}">{{dateText(value,true)}}</template></DataTable><Pagination v-model="state.page" :total="rows.length"/></section><section class="panel alarm-detail"><h2 class="panel-title">选中告警详情</h2><div v-if="selected" class="alarm-facts"><div><span>告警编号</span><strong>{{selected.alarmId}}</strong><span>设备编号</span><button class="btn-link" @click="router.push('/devices/'+selected.deviceId)">{{selected.deviceId}}</button></div><div><span>关联设备</span><strong>{{get('Device',selected.deviceId)?.name||'关联设备不存在'}}</strong></div><div><span>级别</span><StatusBadge :status="selected.severity" :text="severity[selected.severity]" :tone="{HIGH:'danger',MEDIUM:'warning',LOW:'success'}[selected.severity]"/></div><div><span>处理态</span><button class="state-button" aria-label="处置当前告警" @click="open"><StatusBadge :status="selected.status" :text="alarmStates[selected.status]"/></button></div><div><span>恢复态</span><StatusBadge :status="selected.recovery" :text="recovery[selected.recovery]" :tone="selected.recovery==='ACTIVE'?'danger':'success'"/></div><div><span>发生时间</span><strong>{{dateText(selected.openedAt)}}</strong></div><div class="linked-work"><span>关联工单</span><button v-if="work" class="btn-link" @click="router.push({path:'/maintenance',query:{selected:work.workOrderId}})">{{work.workOrderId}}</button><button v-else class="btn-link" @click="open">查看处置</button><span>责任人</span><strong>{{get('User',work?.assigneeId)?.name||'—'}}</strong></div><div><span>工单状态</span><StatusBadge v-if="work" :status="work.status"/><strong v-else>—</strong></div></div><p v-else class="empty-state">没有符合条件的告警，请调整筛选。</p></section><BaseModal :model-value="modal" title="告警处置" :busy="busy" width="740px" @update:model-value="close"><template v-if="snapshot"><p>{{snapshot.alarmId}} · {{get('Device',snapshot.deviceId)?.name}} · {{recovery[snapshot.recovery]}}</p><p class="muted">{{snapshot.handlingNote||'尚无处置记录'}}</p><div class="tabs"><button v-for="(name,action) in {ALARM_ACK:'知悉',WORKORDER_CREATE:'派工',ALARM_CLOSE:'关闭告警'}" :key="action" class="tab" :class="{active:mode===action}" :disabled="busy||!available(action)" @click="mode=action">{{name}}</button></div><p v-if="!mode" class="muted">请选择可用操作。未恢复或工单未验收时不能关闭；已有未完成工单时不能重复派工。</p><WorkOrderForm v-if="mode==='WORKORDER_CREATE'" :draft="draft" :errors="errors" locked :busy="busy"/><FormField v-else-if="mode" :label="mode==='ALARM_CLOSE'?'结案依据（至少12字）':'知悉说明（至少6字）'" required><textarea v-model="note" :disabled="busy" rows="4"/></FormField><p v-if="failure" role="alert" class="error-text">{{failure}}</p></template><template #footer><button class="btn" :disabled="busy" @click="close">取消</button><button class="btn btn-primary" :disabled="busy||!mode||!available(mode)" @click="submit">保存</button></template></BaseModal></div></template>
<style scoped>.alarm-page{gap:8px;padding:0 8px}.alarm-filters{display:flex;gap:28px;height:72px;align-items:flex-start}.alarm-filters .filter-field{width:265px;gap:5px}.alarm-filters select{height:38px}.alarm-page .stat-grid{gap:16px}.alarm-page :deep(.metric-card){height:92px;min-height:0;background:#effaf5}.alarm-page :deep(.metric-warning){background:#fff8e9}.alarm-page :deep(.metric-danger){background:#fff1f1}.alarm-table{overflow:hidden;padding:0}.alarm-table :deep(td){height:28px;padding-top:2px;padding-bottom:2px}.alarm-table :deep(th){height:35px}.state-button{border:0;padding:0;background:none;cursor:pointer}.device-link{color:inherit}.alarm-detail{min-height:185px;padding:14px 19px}.alarm-detail .panel-title{margin-bottom:10px}.alarm-facts{display:grid;grid-template-columns:1.1fr 1.2fr .65fr .75fr .85fr 1.45fr 1.2fr 1fr;gap:12px}.alarm-facts>div{display:flex;align-items:flex-start;flex-direction:column;gap:9px;font-size:14px}.alarm-facts span{color:#647a74}.alarm-facts strong{font-weight:400}.linked-work{border-left:1px solid #dce5e1;padding-left:25px}.alarm-detail .btn-link{font-size:14px}.alarm-table :deep(.pagination){min-height:51px}
</style>
